class TegnaForecastTests(unittest.TestCase):
    def parser(self):
        name = 'bot.feeds.weather_local_tegna'
        self.assertIsNotNone(importlib.util.find_spec(name), 'TEGNA dated transport adapter is missing')
        return importlib.import_module(name).parse_tegna_daily

    def parse(self, capture, **kwargs):
        return self.parser()(capture['html'], city=kwargs.pop('city', capture['city']),
            target_date=kwargs.pop('target_date', '2026-10-19'),
            timezone_name=kwargs.pop('timezone_name', capture['timezone']),
            fetched_at=kwargs.pop('fetched_at', datetime.fromisoformat(capture['fetched_at'])), **kwargs)

    def test_observed_four_station_daily_highs(self):
        for capture in CAPTURES:
            with self.subTest(source=capture['source_id']):
                self.assertEqual(hashlib.sha256(capture['html'].encode()).hexdigest(), capture['fixture_sha256'])
                result = self.parse(capture, measurement_kind='high')
                self.assertEqual(result['high'], capture['expected_high'])
                self.assertIsNone(result['low'])
                self.assertEqual(result['period_start'][:10], '2026-10-19')
                self.assertEqual(result['period_end'][:10], '2026-10-20')
                self.assertEqual(result['forecast_type'], 'local_date_labelled_high_predictor')
                self.assertEqual(result['location']['city'], capture['city'])
                self.assertEqual(result['location']['ianaTimeZone'], capture['timezone'])
                self.assertFalse(result['full_day_measurement_equivalent'])
                self.assertEqual(result['source_clock_basis'], 'capture_time_provider_issue_time_unavailable')
                self.assertIsNone(result['cache_updated_at_ms'])
                self.assertEqual(result['raw_forecast']['date'], 'Oct 19')
                self.assertEqual(result['payload_sha256'], capture['fixture_sha256'])

    def test_observed_four_station_lows_are_target_date_hourly_proxies(self):
        for capture in CAPTURES:
            with self.subTest(source=capture['source_id']):
                result = self.parse(capture, measurement_kind='low')
                self.assertEqual(result['low'], capture['expected_low'])
                self.assertIsNone(result['high'])
                self.assertEqual(result['forecast_type'], 'local_partial_day_hourly_minimum_predictor')
                self.assertEqual(result['period_start'][:10], '2026-10-19')
                self.assertEqual(result['period_end'][:10], '2026-10-19')
                self.assertFalse(result['full_day_measurement_equivalent'])
                # The daily row low is NOT silently assigned to either night.
                self.assertEqual(result['raw_forecast']['daily_low_period_status'], 'unverified_not_used')
                self.assertTrue(all(row['valid_time'][:10] == '2026-10-19'
                                    for row in result['raw_forecast']['hourly_points']))
                self.assertEqual(result['payload_locator'], 'weather-hourly.weather-hourly__row')


    def test_low_provenance_names_the_actual_hourly_clock_mapping(self):
        result = self.parse(CAPTURES[0], measurement_kind='low')
        self.assertEqual(result['date_mapping_basis'], 'displayed_weekday_hour_sequence_anchored_to_capture_local_clock')
        self.assertEqual(result['period_start'], '2026-10-19T00:00:00-04:00')
        self.assertEqual(result['period_end'], '2026-10-19T10:00:00-04:00')
        self.assertEqual(result['period_semantics'], 'forecast_point_sample_bounds_inclusive_not_full_day')


    def test_unsupported_measurement_is_explicit_not_a_high(self):
        from bot.feeds.weather_local import LocalForecastUnavailable
        with self.assertRaisesRegex(LocalForecastUnavailable, '^source_forecast_measurement_kind_unsupported$'):
            self.parse(CAPTURES[0], measurement_kind='current')


    def unavailable(self, capture, reason, **kwargs):
        from bot.feeds.weather_local import LocalForecastUnavailable
        with self.assertRaisesRegex(LocalForecastUnavailable, '^' + reason + '$'):
            self.parse(capture, **kwargs)

    def test_missing_and_naive_capture_clocks_are_explicit(self):
        for clock in (None, datetime(2026, 10, 19)):
            with self.subTest(clock=clock):
                self.unavailable(CAPTURES[0], 'source_forecast_capture_clock_missing', fetched_at=clock)

    def test_city_and_local_timezone_must_match_source_market(self):
        self.unavailable(CAPTURES[0], 'source_forecast_city_mismatch', city='Denver')
        for zone in ('America/Denver', 'not/a_zone', None):
            with self.subTest(zone=zone):
                self.unavailable(CAPTURES[0], 'source_forecast_timezone_mismatch', timezone_name=zone)

    def test_target_year_is_not_inferred_from_request(self):
        self.unavailable(CAPTURES[0], 'target_date_not_in_source_forecast', target_date='2037-10-19')
        self.unavailable(CAPTURES[0], 'target_date_not_in_source_forecast', target_date='2026-10-17')
        self.unavailable(CAPTURES[0], 'source_forecast_target_date_invalid', target_date='not-a-date')

    def test_date_label_weekday_is_checked(self):
        capture = dict(CAPTURES[0], html=CAPTURES[0]['html'].replace('>Mon</span>', '>Tue</span>', 1))
        self.unavailable(capture, 'source_forecast_weekday_mismatch')

    def test_new_year_uses_capture_local_horizon(self):
        # Mutation of the observed layout, not evidence of an extra real capture.
        capture = dict(CAPTURES[0], html=CAPTURES[0]['html'].replace('Oct 19', 'Jan 1', 1).replace('>Mon</span>', '>Fri</span>', 1))
        result = self.parse(capture, target_date='2027-01-01', fetched_at=datetime.fromisoformat('2026-12-31T23:30:00-05:00'))
        self.assertEqual(result['period_start'], '2027-01-01T00:00:00-05:00')

    def test_future_low_is_explicit_while_same_date_high_remains_usable(self):
        for capture in CAPTURES:
            with self.subTest(source=capture['source_id']):
                self.unavailable(capture, 'target_date_missing_low_forecast_period', target_date='2026-10-20', measurement_kind='low')
                self.assertIsNotNone(self.parse(capture, target_date='2026-10-20', measurement_kind='high')['high'])

    def test_low_excludes_previous_evening_and_never_uses_daily_low(self):
        capture = dict(CAPTURES[0], html=CAPTURES[0]['html'].replace('50&deg;', '-10&deg;', 1))
        self.assertEqual(self.parse(capture, measurement_kind='low')['low'], 44)
        prior = self.parse(capture, target_date='2026-10-18', measurement_kind='low')
        self.assertEqual(prior['low'], -10)
        self.assertEqual(prior['period_start'], '2026-10-18T23:00:00-04:00')
        self.assertEqual(prior['period_end'], prior['period_start'])

    def test_broken_hourly_sequence_does_not_suppress_high(self):
        capture = dict(CAPTURES[0], html=CAPTURES[0]['html'].replace('>1 AM</span>', '>3 AM</span>', 1))
        self.unavailable(capture, 'source_hourly_forecast_sequence_invalid', measurement_kind='low')
        self.assertEqual(self.parse(capture, measurement_kind='high')['high'], 69)

    def test_stale_hourly_clock_is_not_redated_to_target(self):
        self.unavailable(CAPTURES[0], 'source_hourly_forecast_clock_ambiguous', measurement_kind='low',
                         fetched_at=datetime.fromisoformat('2026-10-19T14:14:00Z'))

    def test_dst_repeated_hour_without_fold_is_explicit(self):
        capture = dict(CAPTURES[0], html=CAPTURES[0]['html'].replace('>11 PM</span>', '>1 AM</span>', 1))
        self.unavailable(capture, 'source_hourly_forecast_clock_ambiguous', target_date='2026-11-01',
                         fetched_at=datetime.fromisoformat('2026-11-01T05:15:00Z'), measurement_kind='low')

    def test_invalid_numbers_are_not_coerced_to_predictions(self):
        for value in ('NaN', 'Infinity', '131', 'missing'):
            with self.subTest(value=value):
                capture = dict(CAPTURES[0], html=CAPTURES[0]['html'].replace('>69</div>', '>' + value + '</div>', 1))
                self.unavailable(capture, 'source_forecast_temperature_invalid')

    def test_duplicate_daily_date_is_explicit(self):
        capture = dict(CAPTURES[0], html=CAPTURES[0]['html'] + CAPTURES[0]['html'])
        self.unavailable(capture, 'source_forecast_target_date_ambiguous')

    def test_observations_and_script_strings_are_not_forecast_rows(self):
        capture = dict(CAPTURES[0], html=CAPTURES[0]['html'].replace('data-module="weather-10-day"', 'data-module="current-observations"'))
        self.unavailable(capture, 'target_date_not_in_source_forecast')
        capture = dict(CAPTURES[0], html='<script>' + CAPTURES[0]['html'].split('</script>', 1)[1] + '</script>')
        self.unavailable(capture, 'source_forecast_city_missing_or_ambiguous')

    def test_high_does_not_require_hourly_rows(self):
        capture = dict(CAPTURES[0], html=CAPTURES[0]['html'].split('<div data-module="weather-hourly">', 1)[0])
        self.assertEqual(self.parse(capture)['high'], 69)
        self.unavailable(capture, 'target_date_missing_low_forecast_period', measurement_kind='low')


    def test_source_values_are_parsed_not_whitelisted(self):
        capture = dict(CAPTURES[0], html=CAPTURES[0]['html'].replace('>69</div>', '>68.5</div>', 1))
        self.assertEqual(self.parse(capture)['high'], 68.5)

    def test_low_remains_usable_without_a_daily_module(self):
        capture = dict(CAPTURES[0], html=CAPTURES[0]['html'].replace('data-module="weather-10-day"', 'data-module="not-present"'))
        self.assertEqual(self.parse(capture, measurement_kind='low')['low'], 44)

    def test_missing_identity_and_duplicate_fields_are_explicit(self):
        capture = dict(CAPTURES[0], html=CAPTURES[0]['html'].split('</script>', 1)[1])
        self.unavailable(capture, 'source_forecast_city_missing_or_ambiguous')
        duplicate = '<div class="weather-10-day__temperature-high">70</div>'
        capture = dict(CAPTURES[0], html=CAPTURES[0]['html'].replace('>69</div>', '>69</div>' + duplicate, 1))
        self.unavailable(capture, 'source_specific_forecast_schema_invalid')


if __name__ == '__main__':
    unittest.main()
